import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/start/getting-started-contact-list.png",s="/docs/images/start/getting-started-share-dialog.png",i="/docs/images/start/getting-started-edit-together.png",b=JSON.parse('{"title":"Getting started","description":"Sign in, build a small contact list in a sheet, share it with a link, and watch a second person edit it live.","frontmatter":{"title":"Getting started","description":"Sign in, build a small contact list in a sheet, share it with a link, and watch a second person edit it live.","type":"tutorial"},"headers":[],"relativePath":"start/getting-started.md","filePath":"start/getting-started.md"}'),l={name:"start/getting-started.md"};function d(h,t,c,g,p,u){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>In this tutorial you sign in, build a contact list in a sheet, share it with a link, and watch a second person edit it live. It takes about 10 minutes.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need a GitHub account. Some deployments also offer Google sign-in.</li><li>Use a desktop browser. A second browser window, such as a private window, plays your collaborator.</li></ul></div><h2 id="_1-sign-in" tabindex="-1">1. Sign in <a class="header-anchor" href="#_1-sign-in" aria-label="Permalink to &quot;1. Sign in&quot;">​</a></h2><ol><li>Go to <a href="https://wafflebase.io" target="_blank" rel="noreferrer">wafflebase.io</a> and click <strong>Sign in</strong>.</li><li>Click <strong>Continue with GitHub</strong>, or <strong>Continue with Google</strong> if the page offers it.</li><li>Approve the request on the provider&#39;s page.</li></ol><p>Wafflebase opens your workspace on its documents list. Your first sign-in creates the workspace for you.</p><h2 id="_2-create-a-sheet" tabindex="-1">2. Create a sheet <a class="header-anchor" href="#_2-create-a-sheet" aria-label="Permalink to &quot;2. Create a sheet&quot;">​</a></h2><ol><li>Click <strong>New</strong> in the top right of the documents list.</li><li>Select <strong>New sheet</strong>.</li><li>Click the title <strong>New Sheet</strong> in the header, type <code>Team contacts</code>, and press <code>Enter</code>.</li></ol><p>The sheet opens with one tab, <strong>Sheet1</strong>. The sheet&#39;s new name also appears in the documents list.</p><h2 id="_3-add-your-data" tabindex="-1">3. Add your data <a class="header-anchor" href="#_3-add-your-data" aria-label="Permalink to &quot;3. Add your data&quot;">​</a></h2><ol><li><p>Click cell <strong>A1</strong>.</p></li><li><p>Type the data below. Press <code>Tab</code> to move right and <code>Enter</code> to move to the next row.</p><table tabindex="0"><thead><tr><th></th><th>A</th><th>B</th><th>C</th></tr></thead><tbody><tr><td>1</td><td>Name</td><td>Email</td><td>Role</td></tr><tr><td>2</td><td>Alice</td><td><a href="mailto:alice@example.com" target="_blank" rel="noreferrer">alice@example.com</a></td><td>Engineer</td></tr><tr><td>3</td><td>Bob</td><td><a href="mailto:bob@example.com" target="_blank" rel="noreferrer">bob@example.com</a></td><td>Designer</td></tr><tr><td>4</td><td>Carol</td><td><a href="mailto:carol@example.com" target="_blank" rel="noreferrer">carol@example.com</a></td><td>Manager</td></tr></tbody></table></li><li><p>If the emails look cramped, point at the border between column headers <strong>B</strong> and <strong>C</strong>, then drag it to the right.</p></li><li><p>Select cells <strong>A1</strong> to <strong>C1</strong> and click <strong>Bold</strong> in the toolbar.</p></li></ol><p>Your changes save as you type. The header shows <strong>Saving…</strong> and then <strong>Saved</strong>.</p><p><img src="'+n+'" alt="Team contacts sheet with a bold header row and three contacts in columns A to C"></p><h2 id="_4-share-the-sheet" tabindex="-1">4. Share the sheet <a class="header-anchor" href="#_4-share-the-sheet" aria-label="Permalink to &quot;4. Share the sheet&quot;">​</a></h2><ol><li>Click <strong>Share</strong> in the top right of the header.</li><li>Under <strong>Permission</strong>, select <strong>Editor</strong>. You can choose it because you created the sheet.</li><li>Leave <strong>Expiration</strong> set to <strong>No limit</strong>.</li><li>Click <strong>Create link</strong>.</li></ol><p>The link is copied to your clipboard and listed under <strong>Active links</strong>. Anyone with the link can open the sheet without signing in.</p><p><img src="'+s+'" alt="Share document dialog with Permission set to Editor and one link under Active links"></p><h2 id="_5-edit-together" tabindex="-1">5. Edit together <a class="header-anchor" href="#_5-edit-together" aria-label="Permalink to &quot;5. Edit together&quot;">​</a></h2><ol><li>Open a private browser window and paste the link into its address bar.</li><li>In the private window, click cell <strong>A5</strong>, type <code>Dave</code>, and press <code>Enter</code>.</li><li>Switch back to your first window.</li></ol><p><code>Dave</code> appears in cell <strong>A5</strong>. The other window&#39;s selected cell, now <strong>A6</strong>, shows a colored outline labeled <strong>Anonymous</strong>, because that visitor isn&#39;t signed in. The label fades after a few seconds; point at the outline to show it again. Their avatar also appears in the header.</p><p><img src="'+i+'" alt="Team contacts sheet with Dave in A5, a collaborator&#39;s colored outline on A6, and their avatar in the header"></p><p>To stop sharing, open <strong>Share</strong> again and click the trash icon (<strong>Revoke link</strong>) next to the link.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>The same steps work on a phone. To edit a cell, double-tap it and type in the bar at the bottom of the screen, then tap the check mark (<strong>Confirm editing</strong>). See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/sheets/build-a-budget.html">Build a budget</a>: add formulas, number formats, and totals to a sheet</li><li><a href="/docs/collaborate/share.html">Share a document</a>: choose between viewer and editor links, and set an expiration</li><li><a href="/docs/start/concepts.html">Concepts</a>: learn how workspaces, share links, and folders fit together</li><li>Try another editor: <a href="/docs/docs-editor/">Docs</a>, <a href="/docs/slides/">Slides</a>, <a href="/docs/notes/">Notes</a>, or <a href="/docs/board/">Board</a></li></ul>',26)])])}const f=e(l,[["render",d]]);export{b as __pageData,f as default};
